def _setup(client):
    user = client.post("/users", json={"username": "dev", "email": "dev@example.com"}).json()
    project = client.post("/projects", json={"name": "Mercury", "owner_id": user["id"]}).json()
    return user, project


def test_labels_default_empty_and_settable(client):
    user, project = _setup(client)
    resp = client.post("/tasks", json={"title": "A", "project_id": project["id"]})
    assert resp.status_code == 201
    assert resp.json()["labels"] == []

    resp = client.post(
        "/tasks", json={"title": "B", "project_id": project["id"], "labels": ["bug", "urgent"]}
    )
    assert resp.status_code == 201
    assert sorted(resp.json()["labels"]) == ["bug", "urgent"]


def test_label_filter_composes_with_status(client):
    user, project = _setup(client)
    t1 = client.post(
        "/tasks", json={"title": "A", "project_id": project["id"], "labels": ["bug"]}
    ).json()
    t2 = client.post(
        "/tasks", json={"title": "B", "project_id": project["id"], "labels": ["bug"]}
    ).json()
    client.post("/tasks", json={"title": "C", "project_id": project["id"], "labels": ["feature"]})
    client.patch(f"/tasks/{t2['id']}", json={"status": "done"})

    resp = client.get("/tasks", params={"project_id": project["id"], "label": "bug"})
    ids = sorted(t["id"] for t in resp.json())
    assert ids == sorted([t1["id"], t2["id"]]), resp.json()

    resp = client.get(
        "/tasks", params={"project_id": project["id"], "label": "bug", "status": "done"}
    )
    ids = [t["id"] for t in resp.json()]
    assert ids == [t2["id"]], resp.json()

    resp = client.get("/tasks", params={"project_id": project["id"], "label": "nonexistent"})
    assert resp.json() == []


def test_update_replaces_labels(client):
    user, project = _setup(client)
    t = client.post(
        "/tasks", json={"title": "A", "project_id": project["id"], "labels": ["bug"]}
    ).json()
    resp = client.patch(f"/tasks/{t['id']}", json={"labels": ["urgent", "backend"]})
    assert sorted(resp.json()["labels"]) == ["backend", "urgent"]

    resp = client.patch(f"/tasks/{t['id']}", json={"title": "A2"})
    assert sorted(resp.json()["labels"]) == ["backend", "urgent"]


